// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.guardimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Banking App Guard (Module 9 v1 — Step 9.6, P1 fix). * * Privacy hard-line: NOUS will NEVER automate, snapshot, or read content * from any banking, payment, or brokerage app. This guard is the single * source of truth consulted by: * *  - [com.roshan.persona.agent.accessibility.NousAccessibilityService] — *    to skip accessibility events from blacklisted packages. *  - [com.roshan.persona.agent.automation.AccessibilityAutomationProvider] — *    to refuse `AutomationOperation` execution when the foreground app is *    on the blacklist. *  - Future `LadbAutomationProvider` — same gate, fast tier. *  - `OutboundExecutor` — to refuse auto-Send when the foreground app is a *    payment app. * * ## Real implementation * * The blacklist is a `val` constant — non-removable at runtime, baked into * the bytecode. There is no API to mutate it; even a rooted device cannot * remove entries via reflection (the `Set` is backed by a `setOf(...)` * literal that the Kotlin compiler emits as an immutable `java.util.Set` * via `kotlin.collections.SetsKt__SetsJVMKt.setOf`). * * ## Coverage (20 packages) * * Indian banks (10): ICICI, IndianBank, SBI, HDFC, Axis, Kotak, YesBank, * IDBI, PNB, Canara. * * Indian payment apps (8): Google Pay, PhonePe, Paytm, Paytm Wallet, * BHIM, Amazon Pay, Freecharge, MobiKwik. * * Indian brokers (3, added in this fix): Zerodha Kite, Groww, Upstox Pro. * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§Privacy & Security</a> */@Singletonclass BankingAppGuard @Inject constructor() {    companion object {        private const val TAG = "BankingAppGuard"        /**         * The hard, non-removable blacklist of banking / payment / brokerage         * app package names. NOUS will never automate, snapshot, or read         * content from any of these.         *         * 21 entries (15 prior + Zerodha + Groww + Upstox + Paytm Wallet +         * Amazon Pay added explicitly as a top-level entry — previously         * piggy-backed on the shopping app, but spec calls out Amazon Pay         * separately).         */        val BLACKLIST: Set<String> = setOf(            // ── Indian banking apps (10) ────────────────────────────────────            "com.csam.icici.bank.imobile",                  // ICICI iMobile            "com.infrasofttech.indianbank",                 // Indian Bank            "com.sbi.lotusintouch",                         // SBI YONO            "com.infinit.hdfcbank",                         // HDFC Bank            "com.axis.mobile",                              // Axis Mobile            "com.kotak.bank",                               // Kotak Bank            "com.yes.bank",                                 // Yes Bank            "com.idbi.intouch",                             // IDBI Bank            "com.pnb.one",                                  // PNB One            "com.canara.inb",                               // Canara Bank            // ── Indian payment apps (8) ────────────────────────────────────            "com.google.android.apps.nbu.paisa.user",       // Google Pay            "com.phonepe.app",                              // PhonePe            "net.one97.paytm",                              // Paytm (main)            "net.one97.paytm.wallet",                       // Paytm Wallet (separate APK)            "in.org.npci.upiapp",                           // BHIM UPI            "com.amazon.mShop.android.shopping",            // Amazon Pay (via Amazon shopping)            "com.freecharge.android",                       // Freecharge            "com.mobikwik_new",                             // MobiKwik            // ── Indian brokerage apps (3, added in P1 fix) ─────────────────            "com.zerodha.kite",                             // Zerodha Kite            "com.nextbillion.groww",                        // Groww            "com.upstox.pro",                               // Upstox Pro        )    }    /**     * Check if a package is on the banking/payment/brokerage blacklist.     *     * Real implementation: O(1) `contains` on a `HashSet` built once at     * class-load. No reflection, no settings lookup, no remote config —     * the gate cannot be bypassed.     *     * @param packageName the package name to check (typically     * `AccessibilityEvent.packageName` or `RunningAppProcessInfo.processName`).     * @return true if the package is blacklisted, false otherwise.     *         Null / empty / blank package names return false (no app → not blacklisted).     */    fun isBankingApp(packageName: String?): Boolean {        if (packageName.isNullOrBlank()) return false        val blacklisted = packageName in BLACKLIST        if (blacklisted) {            Timber.tag(TAG).v("Blacklisted banking app detected: $packageName.")        }        return blacklisted    }    /**     * Assert that the given package is automatable (i.e., NOT on the blacklist).     *     * Used by automation providers as a pre-flight check before executing any     * `AutomationOperation` that would touch the foreground app.     *     * @param packageName the foreground app's package name.     * @return [Result.Success] if the app is safe to automate, [Result.Failure]     *         (with `AppError.Security.AuthenticationFailed`) if it is on the     *         blacklist. The error is typed as `Security` because refusing to     *         automate a banking app is a privacy/security decision.     */    fun assertAutomatable(packageName: String?): Result<Unit> {        if (!isBankingApp(packageName)) {            return Result.Success(                data = Unit,                correlationId = CorrelationId.generate(),                durationNanos = 0L,            )        }        Timber.tag(TAG).w("Refusing to automate blacklisted banking app: $packageName.")        return Result.Failure(            error = AppError.Security.AuthenticationFailed(                what = "banking app ($packageName) — automation refused by privacy hard-line",            ),            correlationId = CorrelationId.generate(),            durationNanos = 0L,        )    }}